<?php
$esc = function ($value) { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); };
$p = !empty($personnelRecord) ? $personnelRecord : (object) array();
$value = function ($field, $default = '') use ($p) { return isset($p->$field) ? $p->$field : $default; };
$selected = function ($field, $option, $default = '') use ($value) { return $value($field, $default) === $option ? ' selected' : ''; };
$isEdit = !empty($p->id);
$nameParts = preg_split('/\s+/', trim((string) $value('full_name')));
$fallbackFirst = $nameParts[0] ?? '';
$fallbackLast = count($nameParts) > 1 ? implode(' ', array_slice($nameParts, 1)) : '';
$benefits = array_filter(array_map('trim', explode('|', (string) $value('benefits'))));
$hasBenefit = function ($benefit) use ($benefits) { return in_array($benefit, $benefits, true) ? ' checked' : ''; };
?>
