option<?= $selected('employment_status', 'Full-time', 'Full-time'); ?>>Full-time</option><option<?= $selected('employment_status', 'Part-time'); ?>>Part-time</option></select></div></div><div class="form-row"><div class="form-group col-md-4"><label>Salary Range</label><select class="form-control" name="salary_range"><option value="">Select salary range</option><?php foreach(array('Below ₱10,000','₱10,000 – ₱14,999','₱15,000 – ₱19,999','₱20,000 – ₱29,999','₱30,000 – ₱39,999','₱40,000 – ₱49,999','₱50,000 and above') as $option): ?><option<?= $selected('salary_range', $option); ?>><?= $option; ?></option><?php endforeach; ?></select></div><div class="form-group col-md-5"><label>Work Assignment</label><select class="form-control" name="work_assignment"><option value="">Select work assignment</option><?php foreach(array('Top Level/Executive Management','Principal/Assistant Principal','Administrative Officer','Registrar/Records Officer','HR Officer/Secretary','Finance Officer/Accountant','Coordinator') as $option): ?><option<?= $selected('work_assignment', $option); ?>><?= $option; ?></option><?php endforeach; ?></select></div><div class="form-group col-md-3"><label>Working Days / Week</label><select class="form-control" name="working_days_per_week"><option value="">Select days</option><?php foreach(array('1','2','3','4','5','6','7') as $option): ?><option value="<?= $option; ?>"<?= $selected('working_days_per_week', $option); ?>><?= $option; ?> day<?= $option === '1' ? '' : 's'; ?></option><?php endforeach; ?></select></div></div><div class="form-row non-teaching-field"><div class="form-group col-md-6"><label>Non-Teaching Role</label><select class="form-control" name="non_teaching_role" id="nonTeachingRole"><option value="">Select Role</option><?php foreach(array('Registrar','Accountant/Finance','Librarian','Guidance Counselor','Nurse','Cashier','IT Personnel','Administrative Staff','Utility Personnel','Others') as $option): ?><option<?= $selected('non_teaching_role', $option); ?>><?= $option; ?></option><?php endforeach; ?></select></div><div class="form-group col-md-6" id="nonTeachingOther"><label>Please Specify</label><input class="form-control" name="non_teaching_other" value="<?= $esc($value('non_teaching_other')); ?>"></div></div><div class="form-group"><label>Benefits <small class="text-muted">(select all that apply)</small></label><div class="benefits-grid"><?php foreach(array('SSS','GSIS','PhilHealth','Pag-IBIG Fund','13th Month Pay','Leave Benefits','Health Insurance','Rice Allowance') as $benefit): ?><div class="custom-control custom-checkbox"><input class="custom-control-input" type="checkbox" id="benefit<?= md5($benefit); ?>" name="benefits[]" value="<?= $esc($benefit); ?>"<?= $hasBenefit($benefit); ?>><label class="custom-control-label" for="benefit<?= md5($benefit); ?>"><?= $benefit; ?></label></div><?php endforeach; ?></div></div><div class="form-section">Qualifications</div><div class="form-row"><div class="form-group col-md-7"><label>Highest Educational Attainment</label><select class="form-control" name="highest_education"><option value="">Select Educational Attainment</option><?php foreach(array('High School Graduate','Vocational/Technical Certificate','Associate Degree',"Bachelor's Degree","Bachelor's Degree with Professional Education Units","Bachelor's Degree with Master's Units","Master's Degree","Master's Degree with Doctoral Units",'Doctorate Degree') as $option): ?><option<?= $selected('highest_education', $option); ?>><?= $option; ?></option><?php endforeach; ?></select></div><div class="form-group col-md-5"><label>Course / Degree</label><input class="form-control" name="education_course" value="<?= $esc($value('education_course')); ?>"></div></div><div class="form-row teaching-field"><div class="form-group col-md-4"><label>Major / Specialization</label><input class="form-control" name="major_specialization" value="<?= $esc($value('major_specialization')); ?>"></div><div class="form-group col-md-4"><label>PRC License Number</label><input class="form-control" name="prc_license_no" value="<?= $esc($value('prc_license_no')); ?>"></div><div class="form-group col-md-4"><label>PRC Expiration</label><input class="form-control" type="date" name="prc_expiration" value="<?= $esc($value('prc_expiration')); ?>"></div></div><div class="custom-control custom-checkbox mb-4 teaching-field"><input class="custom-control-input" type="checkbox" id="licensed" name="licensed" value="1"<?= !empty($p->licensed) ? ' checked' : ''; ?>><label class="custom-control-label" for="licensed">Licensed Teacher</label></div><div class="form-section">Contact Information</div><div class="form-row"><div class="form-group col-md-6"><label>Email</label><input class="form-control" type="email" name="email" value="<?= $esc($value('email')); ?>"></div><div class="form-group col-md-6"><label>Mobile Number</label><input class="form-control" name="mobile_no" value="<?= $esc($value('mobile_no')); ?>"></div></div></div><div class="card-footer bg-white border-top-0 px-4 px-md-5 pb-4 text-right"><a class="btn btn-light mr-2" href="<?= base_url(); ?>Page/school_personnel">Cancel</a><button class="btn btn-primary" type="submit"><i class="mdi mdi-content-save-outline"></i> <?= $isEdit ? 'Save Changes' : 'Save Personnel'; ?></button></div></form></section></main></div></div></div><script src="<?= base_url(); ?>assets/js/vendor.min.js"></script><script src="<?= base_url(); ?>assets/js/app.min.js"></script><script>document.addEventListener('DOMContentLoaded',function(){var type=document.getElementById('personnelType'),role=document.getElementById('nonTeachingRole'),other=document.getElementById('nonTeachingOther');function refresh(){var teaching=type.value==='Teaching';document.querySelectorAll('.teaching-field').forEach(function(el){el.style.display=teaching?'':'none'});document.querySelectorAll('.non-teaching-field').forEach(function(el){el.style.display=teaching?'none':''});other.style.display=!teaching&&role.value==='Others'?'':'none'}type.addEventListener('change',refresh);role.addEventListener('change',refresh);refresh()});</script></body></html>
